import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class Main {
    public static void main(String[] args) {
        List<String> buah = new ArrayList<>(Arrays.asList("mangga", "apel", "jeruk", "kiwi", "semangka"));

        buah.removeIf(b -> b.length() == 4);
        System.out.println(buah);

        buah.replaceAll(b -> b.toUpperCase());
        buah.sort(Comparator.comparing(String::length).reversed());
        buah.forEach(b -> System.out.println("- " + b));

        Map<String, Integer> stok = new LinkedHashMap<>();
        stok.put("mangga", 12);
        stok.put("jeruk", 0);
        stok.forEach((nama, jumlah) -> System.out.println(nama + ": " + jumlah));
    }
}

